   252→fn get_data_column_sidecars<P: Preset>(
   253→    signed_block_header: SignedBeaconBlockHeader,
   254→    kzg_commitments: &ContiguousList<KzgCommitment, P::MaxBlobCommitmentsPerBlock>,
   255→    kzg_commitments_inclusion_proof: BlobCommitmentsInclusionProof<P>,
   256→    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
   257→) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
   258→    let blob_count = kzg_commitments.len();
   259→    ensure!(
   260→        cells_and_kzg_proofs.len() == blob_count,
   261→        Error::BlobCommitmentsLengthMismatch {
   262→            blob_count,
   263→            commitments_length: kzg_commitments.len(),
   264→        }
   265→    );
   266→
   267→    let mut sidecars = vec![];
   268→    for column_index in 0..P::NumberOfColumns::USIZE {
   269→        let column = ContiguousList::try_from_iter(
   270→            (0..blob_count)
   271→                .map(|row_index| cells_and_kzg_proofs[row_index].0[column_index].clone()),
   272→        )?;
