  2473→fn run_network_service<P: Preset>(
  2474→    mut service: Service<P>,
  2475→    mut network_to_service_rx: UnboundedReceiver<ServiceInboundMessage<P>>,
  2476→    service_to_network_tx: UnboundedSender<ServiceOutboundMessage<P>>,
  2477→) {
  2478→    tokio::spawn(async move {
  2479→        let mut network_metrics_update_interval =
  2480→            IntervalStream::new(tokio::time::interval(NETWORK_METRICS_UPDATE_INTERVAL)).fuse();
  2481→
  2482→        let metrics_enabled = service.network_globals().network_config.metrics_enabled;
  2483→
  2484→        loop {
  2485→            tokio::select! {
  2486→                _ = network_metrics_update_interval.select_next_some(), if metrics_enabled => {
  2487→                    let debug_info = message_debug_info("network_metrics_update_interval");
  2488→
  2489→                    eth2_libp2p::metrics::update_discovery_metrics();
  2490→                    eth2_libp2p::metrics::update_sync_metrics(service.network_globals());
  2491→                    eth2_libp2p::metrics::update_gossipsub_extended_metrics(
  2492→                        service.gossipsub(),
  2493→                        service.network_globals(),
  2494→                    );
  2495→
  2496→                    debug_info.handle();
  2497→                },
  2498→
  2499→                network_event = service.next_event().fuse() => {
  2500→                    ServiceOutboundMessage::NetworkEvent(network_event).send(&service_to_network_tx);
  2501→                }
  2502→
  2503→                message = network_to_service_rx.select_next_some() => {
  2504→                    let debug_info = message_debug_info(&message);
  2505→
  2506→                    match message {
  2507→                        ServiceInboundMessage::DiscoverSubnetPeers(subnet_discoveries) => {
  2508→                            service.discover_subnet_peers(subnet_discoveries);
  2509→                        }
  2510→                        ServiceInboundMessage::GoodbyePeer(peer_id, goodbye_reason, report_source) => {
  2511→                            service.goodbye_peer(&peer_id, goodbye_reason, report_source);
  2512→                        }
  2513→                        ServiceInboundMessage::Publish(message) => {
  2514→                            service.publish(message);
  2515→                        }
  2516→                        ServiceInboundMessage::ReportPeer(peer_id, action, source, msg) => {
  2517→                            service.report_peer(&peer_id, action, source, msg);
  2518→                        }
  2519→                        ServiceInboundMessage::ReportMessageValidationResult(gossip_id, message_acceptance) => {
  2520→                            service.report_message_validation_result(
  2521→                                &gossip_id.source,
  2522→                                gossip_id.message_id,
  2523→                                message_acceptance,
  2524→                            );
  2525→                        }
  2526→                        ServiceInboundMessage::SendErrorResponse(peer_id, inbound_request_id, rpc_error_response, reason) => {
  2527→                            service.send_response(
  2528→                                peer_id,
  2529→                                inbound_request_id,
  2530→                                RpcResponse::Error(rpc_error_response, reason.into()),
  2531→                            );
  2532→                        }
  2533→                        ServiceInboundMessage::SendRequest(peer_id, request_id, request) => {
  2534→                            if let Err(error) = service.send_request(peer_id, request_id, request) {
  2535→                                debug!("Unable to send request to peer: {peer_id}: {error:?}");
  2536→                            }
  2537→                        }
  2538→                        ServiceInboundMessage::SendResponse(peer_id, inbound_request_id, response) => {
  2539→                            service.send_response(peer_id, inbound_request_id, *response);
  2540→                        }
  2541→                        ServiceInboundMessage::Subscribe(gossip_topic) => {
  2542→                            service.subscribe(gossip_topic);
  2543→                        }
  2544→                        ServiceInboundMessage::SubscribeKind(gossip_kind) => {
  2545→                            service.subscribe_kind(gossip_kind);
  2546→                        }
  2547→                        ServiceInboundMessage::SubscribeNewForkTopics(phase, fork_digest) => {
  2548→                            service.subscribe_new_fork_topics(phase, fork_digest);
  2549→                        }
  2550→                        ServiceInboundMessage::Unsubscribe(gossip_topic) => {
  2551→                            service.unsubscribe(gossip_topic);
  2552→                        }
  2553→                        ServiceInboundMessage::UnsubscribeFromForkTopicsExcept(fork_digest) => {
  2554→                            service.unsubscribe_from_fork_topics_except(fork_digest);
